var e=[{id:`travel-checklist`,image:`/images/home/blog-style.jpg`,title:`Что взять с собой в отпуск: полный чек-лист без лишних вещей`,category:`Путешествия`,tags:`#путешествия #отпуск #чеклист #багаж`,excerpt:`Практический список документов, одежды, техники и мелочей, которые стоит проверить перед поездкой.`,author:`Редакция AskHow`,publishedAt:`31 июля 2026`,readTime:`6 минут`,lead:`Собрать чемодан без перегруза проще, когда вещи распределены по понятным категориям. Этот чек-лист поможет ничего не забыть и не брать с собой то, чем вы почти наверняка не воспользуетесь.`,sections:[{heading:`1. Документы и деньги`,paragraphs:[`Начните с вещей, без которых поездка может не состояться. Документы лучше сложить в отдельную небольшую папку или карман ручной клади, чтобы не искать их у стойки регистрации.`],items:[`Паспорт и необходимые визы.`,`Билеты, бронирования жилья и страховка.`,`Банковские карты и небольшой запас наличных.`,`Копии основных документов в телефоне и облачном хранилище.`]},{heading:`2. Одежда: собираем капсулу`,paragraphs:[`Выбирайте вещи, которые сочетаются между собой. Для недельной поездки обычно достаточно нескольких верхов, двух вариантов низа, одного тёплого слоя и удобной обуви.`,`Перед сбором проверьте прогноз погоды и дресс-код мест, которые собираетесь посетить. Это помогает избежать вещей «на всякий случай», занимающих половину чемодана.`],items:[`Базовые футболки или рубашки.`,`Брюки, джинсы или шорты по погоде.`,`Лёгкая куртка, кофта или дождевик.`,`Нижнее бельё и носки на каждый день с небольшим запасом.`,`Удобная повседневная обувь и одна дополнительная пара.`]},{heading:`3. Аптечка и гигиена`,paragraphs:[`Берите только те лекарства, которыми умеете пользоваться, а рецептурные препараты перевозите в оригинальной упаковке. Косметику удобно перелить в дорожные ёмкости небольшого объёма.`],items:[`Регулярные лекарства и рецепты при необходимости.`,`Пластыри, обезболивающее и средство от расстройства пищеварения.`,`Зубная щётка, паста, дезодорант и расчёска.`,`Солнцезащитное средство и средство после загара.`,`Антисептик и влажные салфетки.`]},{heading:`4. Техника и зарядки`,paragraphs:[`Соберите всю технику в одном месте до упаковки. Проверьте тип розеток в стране назначения: иногда понадобится переходник.`],items:[`Телефон и зарядное устройство.`,`Наушники и внешний аккумулятор.`,`Переходник для розетки.`,`Камера, карта памяти и запасной аккумулятор, когда они действительно нужны.`]},{heading:`5. Что положить в ручную кладь`,paragraphs:[`В ручной клади должны быть документы, деньги, лекарства, техника и минимум вещей на случай задержки багажа. Ценные предметы лучше не сдавать в багаж.`],items:[`Документы и кошелёк.`,`Телефон, зарядка и пауэрбанк.`,`Лекарства первой необходимости.`,`Наушники, маска для сна и пустая бутылка для воды.`,`Футболка и комплект белья для длительного перелёта.`]}],conclusion:`Перед выходом проверьте четыре вещи: паспорт, телефон, деньги и лекарства. Всё остальное при необходимости можно купить на месте. Чем проще и логичнее собран багаж, тем спокойнее начинается поездка.`}];function t(t){return e.find(e=>e.id===t)}export{t as n,e as t};